        new Solver();
    }

    static class Solver {
        IO io;

        public Solver() {
            this.io = new IO();
            try {
                execute();
            } catch (RuntimeException e) {
                if (!e.getMessage().equals("Clean exit")) {
                    throw e;
                }
            } finally {
                io.close();
            }
        }

        void execute() {
            long n = io.nextLong();
            long m = io.nextLong();
            if (m < n) {
                long temp = m;
                m = n;
                n = temp;
            }

            if (n == 1) {
                io.println(bruteForce(m));
                return;
            }
            if (n == 2) {
                if (m < 3) io.println(0);
                else if (m == 3) io.println(4);
                else if (m == 7) io.println(12);
                else io.println(2 * m);
                return;
            }

            io.println(2 * (n * m / 2));
        }

        long bruteForce(long m) {
            long result = 6 * (m / 6);
            if (m % 6 == 5) result += 4;
            else if (m % 6 == 4) result += 2;
            return result;
        }
    }

    static class IO extends PrintWriter {
        private InputStreamReader reader;
        private static final int BUFSIZE = 1 << 15;
        private char[] buffer;
        private int bufCount;
        private int bufIndex;
        private StringBuilder stringBuilder;

        public IO() {
            super(new BufferedOutputStream(System.out));
            reader = new InputStreamReader(System.in);
            buffer = new char[BUFSIZE];
            bufCount = 0;
            bufIndex = 0;
            stringBuilder = new StringBuilder();
        }

        private void fillBuffer() throws IOException {
            bufCount = reader.read(buffer, 0, BUFSIZE);
            bufIndex = 0;
        }

        private boolean hasNextChar() throws IOException {
            if (bufIndex >= bufCount) {
                fillBuffer();
            }
            return bufCount > 0;
        }

        private boolean isDelimiter(char c) {
            return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
        }

        private void skipDelimiters() throws IOException {
            while (true) {
                if (!hasNextChar()) {
                    break;
                }
                if (!isDelimiter(buffer[bufIndex])) {
                    break;
                }
                bufIndex++;
            }
        }

        public String next() {
            try {
                stringBuilder.setLength(0);
                skipDelimiters();
                int start = bufIndex;
                while (true) {
                    if (!hasNextChar()) {
                        break;
                    }
                    if (isDelimiter(buffer[bufIndex])) {
                        break;
                    }
                    bufIndex++;
                }
                stringBuilder.append(buffer, start, bufIndex - start);
                return stringBuilder.toString();
            } catch (IOException e) {
                throw new RuntimeException("IO.next: IOException");
            }
        }

        public long nextLong() {
            try {
                long result = 0;
                boolean positive = true;
                skipDelimiters();
                if (buffer[bufIndex] == '-') {
                    positive = false;
                    bufIndex++;
                }
                while (true) {
                    if (!hasNextChar()) {
                        break;
                    }
                    if (isDelimiter(buffer[bufIndex])) {
                        break;
                    }
                    result = result * 10 + (buffer[bufIndex] - '0');
                    bufIndex++;
                }
                return positive ? result : -result;
            } catch (IOException e) {
                throw new RuntimeException("IO.nextLong: IOException");
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }
}
